# HTML/long descriptions (non-article)
T["Survival Trail \u2014 Interactive Wilderness Simulator"] = "Sentier de Survie \u2014 Simulateur Interactif de Nature"
T["Operation Wildwood \u2014 Bushcraft & Survival Training"] = "Operation Wildwood \u2014 Formation Techniques de Brousse & Survie"
T["You can survive only 3 days without water. Always locate and purify a water source early."] = "On ne peut survivre que 3 jours sans eau. Localisez et purifiez toujours une source d'eau tot."
T["Hypothermia is the number one wilderness killer. Shelter and fire are your first priorities in cold conditions."] = "L'hypothermie est le tueur en milieu sauvage numero un. L'abri et le feu sont vos premieres priorites dans le froid."
T["Pain, Cold, Thirst, Hunger, Fatigue, Boredom, and Loneliness erode your will to survive. Maintain a positive attitude."] = "Douleur, Froid, Soif, Faim, Fatigue, Ennui et Solitude erodent votre volonte de survivre. Maintenez une attitude positive."
T["Eating unknown plants or mushrooms can be fatal. If you cannot identify it with certainty, do not eat it."] = "Manger des plantes ou champignons inconnus peut etre fatal. Si vous ne pouvez pas l'identifier avec certitude, ne le mangez pas."
T["Check the CFFDRS rating before lighting any fire. Extreme conditions mean no open flames permitted."] = "Verifiez la cote CFFDRS avant d'allumer un feu. Les conditions extremes signifient aucune flamme nue autorisee."
T["Wilderness survival hazards cadets must remain aware of in the field. Threat levels update as you progress."] = "Dangers de survie en milieu sauvage dont les cadets doivent rester conscients sur le terrain. Les niveaux de menace se mettent a jour a mesure que vous progressez."
T["Use the universal distress signal: three of everything. Multiple methods maximize visibility."] = "Utiliser le signal de detresse universel : trois de tout. Plusieurs methodes maximisent la visibilite."

# Welcome/briefing texts
T["As you complete bushcraft and survival training modules and earn XP, you advance through the survival ranks. Each rank unlocks new responsibilities and recognition in the field."] = "Au fur et a mesure que vous completez les modules de formation en techniques de brousse et survie et gagnez des PE, vous avancez dans les grades de survie. Chaque grade debloque de nouvelles responsabilites et une reconnaissance sur le terrain."
T["Track your progress across bushcraft and survival training modules. XP is awarded for completing mission tasks correctly. Wrong attempts reduce your mission score but you can retry."] = "Suivez votre progression a travers les modules de formation en techniques de brousse et survie. Des PE sont attribues pour avoir complete correctement les taches de mission. Les mauvaises tentatives reduisent votre score de mission mais vous pouvez reessayer."
T["What is your top priority for the next 2 hours of daylight?"] = "Quelle est votre priorite principale pour les 2 prochaines heures de lumiere du jour ?"

# Save the dictionary
with open('fr_bushcraft_dict.json', 'w', encoding='utf-8') as f:
    json.dump(T, f, ensure_ascii=True, indent=2)

# Check coverage
short_strings = [s for s in all_strings if '<p>' not in s and len(s) < 200]
missing_short = [s for s in short_strings if s not in T]
long_strings = [s for s in all_strings if '<p>' in s or len(s) >= 200]
missing_long = [s for s in long_strings if s not in T]

print(f"Short strings: {len(short_strings)}, translated: {len(short_strings)-len(missing_short)}, missing: {len(missing_short)}")
print(f"Long strings: {len(long_strings)}, translated: {len(long_strings)-len(missing_long)}, missing: {len(missing_long)}")
if missing_short:
    print("\n=== MISSING SHORT ===")
    for m in missing_short[:20]:
        print(repr(m))
    if len(missing_short) > 20:
        print(f"... and {len(missing_short)-20} more")
